mapper.select:
SELECT mn.id, mn.p_id, mn.pp_type, mn.pp_current, mn.progress, mn.sec_id, mn.p_date, mn.remark, mn.file_status, mn.create_uid, mn.create_time, mn.create_uname, mn.state, mn.state_time, mn.img_show, pre.p_Name AS pName, sf.file_relation_id as fileRelationId FROM project_profile mn INNER JOIN ( SELECT p_id, MAX(create_time) AS max_create_time FROM project_profile WHERE 1=1
AND p_id = #{params.pId}
AND pp_type = #{params.ppType}
AND pp_current = #{params.ppCurrent}
AND progress = #{params.progress}
AND sec_id = #{params.secId}
AND p_date = #{params.pDate}
AND remark LIKE CONCAT('%', #{params.remark}, '%')
AND file_status = #{params.fileStatus}
AND create_uid = #{params.createUid}
AND create_uname LIKE CONCAT('%', #{params.createUname}, '%')
AND state = #{params.state}
AND state_time = #{params.stateTime}
AND img_show = #{params.imgShow}
AND p_name LIKE CONCAT('%', #{params.pName}, '%')
GROUP BY p_id ) latest ON mn.p_id = latest.p_id AND mn.create_time = latest.max_create_time LEFT JOIN pre_project pre ON mn.p_id = pre.p_id left join Sys_File sf on sf.FileID = mn.id
ORDER BY ${params.sortFiled} ${params.sortType}
